/**
 * @param {string} s
 * @param {string[][]} knowledge
 * @return {string}
 */
var evaluate = function(s, knowledge) {
    const map = new Map(knowledge);

    let reading = false;
    let temp = '';
    let res = '';

    for (const char of s) {
        if (char === '(') {
            reading = true;
            temp = '';
        } else if (char === ')') {
            reading = false;
            res += map.get(temp) ?? '?';
        } else if (reading) {
            temp += char;
        } else {
            res += char;
        }
    }

    return res;
};

/**
 * @param {string} s
 * @param {string[][]} knowledge
 * @return {string}
 */
var evaluate = function(s, knowledge) {
    const map = new Map(knowledge);

    return s.split(/\(|\)/)
        .map((x, i) => i & 1 ? map.get(x) ?? '?' : x)
        .join('');
};
